// Handles post-purchase NPC item refresh. For gamble mode (nBuyMode==2) with a personal NPC inventory, scans the player's carried items and refreshes the matching gamble item via SUNITNPC_RefreshNpcItem. Otherwise checks if the NPC can still sell the item; if not, refills the NPC's inventory slot via SUNITNPC_FillNpcInventory.
void __fastcall SUNITNPC_DeductGoldForPurchase(::SGAMEDATA * pGame, D2UnitStrc * pUnit, D2UnitStrc * param_1, D2UnitStrc * pPlayerRaw, int32_t nBuyMode) {
    D2UnitStrc* pFirstItem;
    D2UnitStrc* pCarriedItem;
    int nClientGUID;
    int nNpcIndex;
    int* pNpcListNode;
    D2UnitStrc* pUnitSave = pUnit;
    ::SGAMEDATA* pGameSave = pGame;
    D2GameNpcStrc* pGameNpc = sunitproxy::GetGameNpcByUnit(pGame, pUnit, &nNpcIndex);
    if (pGameNpc->flags0x0C && nBuyMode == 2) {
      D2NpcProxyInventoryStrc* pDVar1;
      pDVar1 = pGameNpc->pProxyInventories;
      if (!pPlayerRaw) {
        nClientGUID = -1;
      } else {
        nClientGUID = pPlayerRaw->nUnitGUID;
      }

      for (; pDVar1; pDVar1 = pDVar1->pNext) {
        if (pDVar1->nPlayerGUID == nClientGUID) {
          if (pDVar1->pInventory) {
            pFirstItem = D2Common::INVENTORY::Inventory::INVENTORY_GetFirstItem(pDVar1->pInventory);
            pGame = pGameSave;
            while (true) {
              pGameSave = pGame;
              if (!pFirstItem) {
                break;
              }

              pCarriedItem = D2Common::INVENTORY::Inventory::GetCarriedItem(pFirstItem);
              pFirstItem = D2Common::INVENTORY::Inventory::INVENTORY_GetNextItem(pFirstItem);
              pUnit = pUnitSave;
              pGame = pGameSave;
              if (pCarriedItem == param_1) {
                SUNITNPC_RefreshNpcItem(pPlayerRaw, pUnitSave, param_1, pGameSave, 1);
                return;
              }
            }
          }

          break;
        }
      }
    }

    bool bVar2 = SUNITNPC_CheckNpcCanSellItem(pGame, pUnit, param_1);
    if (bVar2) {
      return;
    }

    SUNITNPC_FillNpcInventory(pUnit, param_1, pGame, 1);
}

// Checks the hireling slot array for an NPC (indexed by nNpcClassId via D2HirelingTxt name range). If all slots with valid entries are unfilled (count==0), frees the slot array, clears the pointer and a flags byte, then re-initialises the NPC's hireling inventory via SUNITNPC_InitNpcInventory. Halts if the hireling entry or name range is invalid.
// @sourcefile .\UNIT\SUNITNPC.CPP
void __fastcall ResetNpcHireListIfEmpty(::SGAMEDATA * pGame, int32_t nNpcClassId, uint32_t nFilledSlots) {
    int nNameRange;
    uint32_t pNpcData = nFilledSlots;
    int pHireSlotArray = *(int*)(nFilledSlots + 0x10);
    nFilledSlots = 0;
    D2HirelingTxt* pHirelingTxt = D2Common::DATATBLS::MonsterTbls::GetHirelingEntry(pGame->bExpansion, nNpcClassId, 0, 0);
    if (!pHirelingTxt) {
      *(volatile uint8_t*)0x0 = 0;
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x632);
      exit(-1);
    } else {
      int* pSlotEntry;
      nNameRange = (uint32_t)pHirelingTxt->nNameLast - (uint32_t)pHirelingTxt->nNameFirst + 1;
      if (nNameRange == -1) {
        Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x60);
        exit(-1);
      }
      if (nNameRange > 0) {
        pSlotEntry = (int*)(pHireSlotArray + 8);
        do {
          if (pSlotEntry[1] && !*pSlotEntry) {
            nFilledSlots++;
          }

          pSlotEntry += 4;
          nNameRange--;
        } while (nNameRange);

        if (nFilledSlots) {
          return;
        }
      }

      D2_FREE_POOL_AT(pGame->pMemoryPool, *(void**)(pNpcData + 0x10), ".\\UNIT\\SUNITNPC.CPP", 0x63d);
      *(uint32_t*)(pNpcData + 0x10) = 0;
      *(uint8_t*)(pNpcData + 0x21) = 0;
      SUNITNPC_InitNpcInventory(pGame, nNpcClassId, pNpcData);
      return;
    }
}

// Server-side handler for hiring a mercenary from a town NPC. Validates the NPC and that quest gates are met (Qualkehk/0x203 requires RescueOnMountArreat; Akara/0x96 requires SistersBurialGrounds before higher-cost mercs). Looks up the game NPC record and the requested merc by name id (range-checked against GetHirelingNamesAndSize), rolls the merc's stats/cost (RollMercStats), checks the player can afford it (CheckIfPlayerCanAffordCost), then spawns the merc monster (SpawnMonster) and binds it to the player (MERC_HireAndReplaceMerc). On success marks the hire slot taken, refreshes the for-hire list, and sends an NPC-transaction result (0x2A, code 5). On any failure sends 0x2A with an error code (9/0xb/0xc/0xf) and current gold. Side effects: spawns a unit, mutates NPC hire slots, sends packets to the player's client.
// @sourcefile .\UNIT\SUNITNPC.CPP
