    D2MercForHire* pHireSlot;
    D2MonsterAiStrc* pNpcMonsterAi;
    D2ClientStrc* pClientSend;
    uint32_t bFirstInteraction;
    D2UnitStrc* pClient;
    uint8_t nResult;
    uint8_t nTradeType_00;
    D2HirelingHireData sMercHireData;
    int32_t nNpcDataIdx;
    uint32_t nNameLast;
    uint32_t nNameFirst;
    int32_t nClassId;
    int32_t nNcpClassId;
    int32_t nUnitGUID;
    int32_t nLineNum;
    int32_t nPlayerLevel;
